create or replace function public.crm_next_best_action(p_conversation_id uuid) returns jsonb language sql stable security invoker set search_path=public as $$ with c as (select * from public.crm_conversations where id=p_conversation_id and user_id=auth.uid()), s as (select coalesce(sum(case when lower(coalesce(status,'')) in ('approved','paid','completed','succeeded') then coalesce(amount,0) else 0 end),0) revenue,count(*) filter(where lower(coalesce(status,'')) in ('approved','paid','completed','succeeded')) approved_sales,count(*) total_sales from public.sales where user_id=auth.uid() and ((select buyer_email from c) is not null and lower(coalesce(data->>'email',data->>'buyer_email',data->>'customer_email',''))=lower((select buyer_email from c)) or (select transaction_id from c) is not null and transaction_id::text=(select transaction_id::text from c))), m as (select count(*) inbound_count from public.crm_messages where user_id=auth.uid() and conversation_id=p_conversation_id and direction='inbound'), o as (select count(*) pending from public.crm_webhook_events where user_id=auth.uid() and (select transaction_id from c) is not null and transaction_id::text=(select transaction_id::text from c) and lower(coalesce(status,'')) in ('pending','waiting','requires_action')), d as (select case when (select pending from o)>0 then 'payment_follow_up' when (select approved_sales from s)>0 then 'upsell_or_post_sale' when (select inbound_count from m)>0 then 'sales_follow_up' when (select total_sales from s)>0 then 'recovery_follow_up' else 'qualification' end action,case when (select pending from o)>0 then .92 when (select approved_sales from s)>0 then .86 when (select inbound_count from m)>0 then .81 when (select total_sales from s)>0 then .76 else .55 end probability) select jsonb_build_object('conversation_id',p_conversation_id,'action',d.action,'probability',d.probability,'revenue',s.revenue,'approved_sales',s.approved_sales,'inbound_count',m.inbound_count,'pending_payment_events',o.pending,'reason',case d.action when 'payment_follow_up' then 'Pagamento pendente exige intervenção imediata.' when 'upsell_or_post_sale' then 'Cliente com compra aprovada: avançar no pós-venda ou upsell.' when 'sales_follow_up' then 'Cliente iniciou conversa e requer condução comercial.' when 'recovery_follow_up' then 'Há histórico de tentativa de compra sem aprovação.' else 'Poucos sinais comerciais: priorizar qualificação.' end,'generated_at',timezone('utc',now())) from s,m,o,d; $$; revoke all on function public.crm_next_best_action(uuid) from public; grant execute on function public.crm_next_best_action(uuid) to authenticated;